import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Minecraft Terms","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/extensions/minecraft-terms/README.md"},"headers":[],"relativePath":"extensions/minecraft-terms/README.md","filePath":"extensions/minecraft-terms/README.md","lastUpdated":1792252155000}`),a={name:`extensions/minecraft-terms/README.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="minecraft-terms" tabindex="-1">Minecraft Terms <a class="header-anchor" href="#minecraft-terms" aria-label="Permalink to “Minecraft Terms”">​</a></h1><p>This extension adds Minecraft terminology to <a href="https://marketplace.visualstudio.com/items?itemName=streetsidesoftware.code-spell-checker" target="_blank" rel="noreferrer">Code Spell Checker</a>. The same dictionary is available to the <a href="https://www.npmjs.com/package/cspell" target="_blank" rel="noreferrer"><code>cspell</code></a> command-line linter through <code>@pumpkin-plugins/cspell-dict-minecraft</code>. It covers Minecraft terms and names, not PumpkinMC-specific terminology.</p><p>See the <a href="https://filiphsps.github.io/pumpkin-plugins/api/extensions/minecraft-terms/" target="_blank" rel="noreferrer">API reference</a> on the documentation site.</p><p>To use the dictionary in VS Code, install Code Spell Checker and this extension. When VS Code starts, the extension registers its packaged dictionary with Code Spell Checker. In an npm project, install <code>@pumpkin-plugins/cspell-dict-minecraft</code> and import its <code>cspell-ext.json</code> in your CSpell configuration. The <a href="/pumpkin-plugins/tools/cspell-dict-minecraft/README#install">dictionary package&#39;s install instructions</a> include the pnpm command and a YAML example.</p><p>The GitHub release includes a VSIX for this extension. To install it, download the <code>.vsix</code> file, then in VS Code select <strong>Extensions: Install from VSIX...</strong> and choose that file.</p><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to “License”">​</a></h2><p>MIT.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};